#include "lang/jxx.lang.IllegalArgumentException.h"
#include "lang/jxx.lang.NullPointerException.h"
namespace jxx::swing { JMenuBar::JMenuBar():Super(),selectionModel_(::jxx::NEW<DefaultSingleSelectionModel>()){} ::jxx::Ptr<JMenu> JMenuBar::add(const ::jxx::Ptr<JMenu>& menu){if(!menu)throw ::jxx::lang::NullPointerException("menu");menus_.push_back(menu);return menu;} ::jxx::lang::jint JMenuBar::getMenuCount()const{return static_cast<::jxx::lang::jint>(menus_.size());} ::jxx::Ptr<JMenu> JMenuBar::getMenu(::jxx::lang::jint index)const{if(index<0||index>=static_cast<::jxx::lang::jint>(menus_.size()))throw ::jxx::lang::IllegalArgumentException("index");return menus_[index];} void JMenuBar::setHelpMenu(const ::jxx::Ptr<JMenu>& menu){helpMenu_=menu;} ::jxx::Ptr<JMenu> JMenuBar::getHelpMenu()const{return helpMenu_;} void JMenuBar::setSelectionModel(const ::jxx::Ptr<SingleSelectionModel>& model){if(!model)throw ::jxx::lang::NullPointerException("model");selectionModel_=model;} ::jxx::Ptr<SingleSelectionModel> JMenuBar::getSelectionModel()const{return selectionModel_;} ::jxx::lang::jbool JMenuBar::isSelected()const{return selectionModel_&&selectionModel_->isSelected();} }
